1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace AtrioTeam\DigitalHub\Tags\Filament;
6	
7	use AtrioTeam\DigitalHub\Tags\Enum\TagTarget;
8	use AtrioTeam\DigitalHub\Tags\Models\Tag;
9	use AtrioTeam\DigitalHub\Tags\Models\TagCategory;
10	use AtrioTeam\DigitalHub\Tags\Models\TagGroup;
11	use Closure;
12	use Filament\Forms\Components\Select;
13	use Filament\Schemas\Components\Fieldset;
14	use Filament\Schemas\Components\Section;
15	use Illuminate\Database\Eloquent\Builder;
16	use Illuminate\Database\Eloquent\Model;
17	use Illuminate\Database\Eloquent\Relations\MorphToMany;
18	
19	/**
20	 * Sezione dei tag associabili, con vincolo rigido: considera solo i gruppi
21	 * filtrati per l'entità data e per il target dato (entity|asset) e produce,
22	 * per ogni gruppo, un Fieldset con un Select a scelta multipla per ogni sua
23	 * categoria, con i soli tag della categoria come opzioni. Condiviso fra i form
24	 * delle entità e il picker degli asset nell'AssetManager.
25	 */
26	class TagPicker
27	{
28	    /**
29	     * Picker legato alla relazione `tags` del record del form (entità che usa
30	     * HasTags): ogni select carica/sincronizza sul pivot `taggables` i soli tag
31	     * della propria categoria, senza toccare quelli delle altre.
32	     *
33	     * `$scopeGroupsUsing` (opzionale) restringe ulteriormente i gruppi: riceve
34	     * la query dei TagGroup come parametro nominato `query` e viene valutata da
35	     * Filament, quindi supporta l'injection dei parametri di contesto (es.
36	     * `$livewire`). Permette all'app vincoli propri (es. la Destinazione
37	     * Category1) senza che il package li conosca.
38	     */
39	    public static function make(string $entityAlias, TagTarget $target, ?Closure $scopeGroupsUsing = null): Section
40	    {
41	        // schema lazy: i gruppi possono dipendere dal contesto ($livewire) via
42	        // $scopeGroupsUsing, valutato da Filament sul componente
43	        return self::section()->schema(function (Section $component) use ($entityAlias, $target, $scopeGroupsUsing): array {
44	            $scopeGroups = $scopeGroupsUsing === null ? null : function (Builder $groupQuery) use ($component, $scopeGroupsUsing): void {
45	                $component->evaluate($scopeGroupsUsing, ['query' => $groupQuery]);
46	            };
47	
48	            return array_map(
49	                fn (TagGroup $group): Fieldset => self::groupFieldset($group, self::relationshipSelect(...)),
50	                self::groups($entityAlias, $target, $scopeGroups),
51	            );
52	        });
53	    }
54	
55	    /**
56	     * Picker "standalone" (senza relationship): lo stato è un array di id tag
57	     * per categoria, sotto la chiave `tags` (`tags.{categoryId}` => int[]).
58	     * Per contesti senza record bindato al form (es. azione nell'AssetManager),
59	     * dove fill/sync sono gestiti a mano dal chiamante.
60	     */
61	    public static function makeStandalone(string $entityAlias, TagTarget $target): Section
62	    {
63	        return self::section()->schema(fn (): array => array_map(
64	            fn (TagGroup $group): Fieldset => self::groupFieldset($group, self::categorySelect(...)),
65	            self::groups($entityAlias, $target, null),
66	        ));
67	    }
68	
69	    private static function section(): Section
70	    {
71	        return Section::make(__('digital-hub::tag.model_plural'));
72	    }
73	
74	    /**
75	     * Fieldset del gruppo, con un select per ogni sua categoria (con almeno un
76	     * tag) costruito dal factory dato (variante con relationship o standalone).
77	     *
78	     * @param Closure(TagCategory): Select $makeSelect
79	     */
80	    private static function groupFieldset(TagGroup $group, Closure $makeSelect): Fieldset
81	    {
82	        return Fieldset::make((string) $group->name)
83	            ->columns(2)
84	            ->columnSpanFull()
85	            ->schema(
86	                $group->categories
87	                    ->filter(fn (TagCategory $category): bool => $category->tags->isNotEmpty())
88	                    ->sortBy('id')
89	                    ->map($makeSelect)
90	                    ->values()
91	                    ->all(),
92	            );
93	    }
94	
95	    /**
96	     * Select della categoria per la variante con relationship: stato caricato e
97	     * salvato a mano sul pivot (via gli stessi hook usati da
98	     * Select::relationship()), limitato ai tag della categoria perché più
99	     * select condividono la stessa relazione `tags`.
100	     */
101	    private static function relationshipSelect(TagCategory $category): Select
102	    {
103	        $categoryId = (int) $category->id;
104	        $categoryTagIds = array_map(fn ($id): int => (int) $id, $category->tags->modelKeys());
105	
106	        return self::categorySelect($category)
107	            ->dehydrated(false)
108	            ->loadStateFromRelationshipsUsing(function (Select $component, ?Model $record) use ($categoryId): void {
109	                if ($record === null) {
110	                    return;
111	                }
112	
113	                $component->state(
114	                    self::tagsRelation($record)
115	                        ->where('tag_category_id', $categoryId)
116	                        ->pluck('tags.id')
117	                        ->all(),
118	                );
119	            })
120	            ->saveRelationshipsUsing(function (Select $component, ?Model $record) use ($categoryTagIds): void {
121	                if ($record === null) {
122	                    return;
123	                }
124	
125	                $selected = array_values(array_intersect(
126	                    array_map(fn (mixed $id): int => is_scalar($id) ? (int) $id : 0, (array) $component->getState()),
127	                    $categoryTagIds,
128	                ));
129	
130	                $relation = self::tagsRelation($record);
131	                $relation->detach(array_values(array_diff($categoryTagIds, $selected)));
132	                $relation->syncWithoutDetaching($selected);
133	            });
134	    }
135	
136	    /**
137	     * Select multiplo con i tag della categoria come opzioni. Lo statePath
138	     * annidato `tags.{categoryId}` tiene tutte le selezioni sotto `tags`.
139	     */
140	    private static function categorySelect(TagCategory $category): Select
141	    {
142	        $options = [];
143	        foreach ($category->tags as $tag) {
144	            $options[(int) $tag->id] = (string) $tag->name;
145	        }
146	
147	        return Select::make('tags.' . (int) $category->id)
148	            ->label((string) $category->name)
149	            ->multiple()
150	            ->searchable()
151	            ->options($options)
152	            ->default([]);
153	    }
154	
155	    /**
156	     * Gruppi filtrati per entità e target, più l'eventuale vincolo aggiuntivo
157	     * passato dal chiamante, con le loro categorie (e relativi tag). Le
158	     * categorie senza tag e i gruppi rimasti senza categorie sono esclusi.
159	     *
160	     * @param (Closure(Builder<TagGroup>): void)|null $scopeGroups query dei TagGroup
161	     * @return array<int, TagGroup>
162	     */
163	    private static function groups(string $entityAlias, TagTarget $target, ?Closure $scopeGroups): array
164	    {
165	        $groupQuery = TagGroup::query()
166	            ->where('entity_type', $entityAlias)
167	            ->where('target', $target->value)
168	            ->whereHas('categories', function (Builder $categoryQuery): void {
169	                $categoryQuery->whereHas('tags');
170	            })
171	            ->with('categories.tags')
172	            ->orderBy('id');
173	
174	        if ($scopeGroups !== null) {
175	            $scopeGroups($groupQuery);
176	        }
177	
178	        return $groupQuery->get()->all();
179	    }
180	
181	    /**
182	     * Relazione tags() del record (HasTags di spatie), tipizzata qui perché dal
183	     * form il record arriva come Model generico.
184	     *
185	     * @return MorphToMany<Tag, Model>
186	     */
187	    private static function tagsRelation(Model $record): MorphToMany
188	    {
189	        assert(method_exists($record, 'tags'));
190	
191	        /** @var MorphToMany<Tag, Model> $relation */
192	        $relation = $record->tags();
193	
194	        return $relation;
195	    }
196	}
