34	            groups: @js($getGroups()),
35	            init() {
36	                if (! Array.isArray(this.state)) {
37	                    this.state = [];
38	                }
39	            },
40	            countSelected(ids) {
41	                return ids.filter((id) => this.state.includes(id)).length;
42	            },
43	            isAll(ids) {
44	                return ids.length > 0 && ids.every((id) => this.state.includes(id));
45	            },
46	            isSome(ids) {
47	                const n = this.countSelected(ids);
48	                return n > 0 && n < ids.length;
49	            },
50	            toggleCategory(ids, checked) {
51	                if (checked) {
52	                    ids.forEach((id) => {
53	                        if (! this.state.includes(id)) {
54	                            this.state.push(id);
55	                        }
56	                    });
57	                } else {
58	                    this.state = this.state.filter((id) => ! ids.includes(id));
59	                }
