5	namespace Tests\Feature\Products;
6	
7	use App\Filament\Resources\Products\Pages\ListProducts;
8	use App\Models\Category1;
9	use App\Models\Category2;
10	use App\Models\Material;
11	use App\Models\MaterialCategory;
12	use App\Models\Product;
13	use App\Models\ProductType;
14	use App\Models\User;
15	use AtrioTeam\DigitalHub\Pim\Filament\Tables\DigitalHubTableMacro;
16	use Filament\Facades\Filament;
17	use Illuminate\Foundation\Testing\RefreshDatabase;
18	use Livewire\Livewire;
19	use Tests\TestCase;
20	
21	/**
22	 * NestedCheckboxSelect nel ProductForm: la relazione materials/fabrics è salvata
23	 * a livello di singolo item. Verifica che l'EditAction in slideOver (il path che
24	 * gestisce i prodotti) carichi lo stato dalla relazione e la sincronizzi al save.
25	 */
26	class ProductMaterialsNestedSelectTest extends TestCase
27	{
28	    use RefreshDatabase;
29	
30	    protected function setUp(): void
31	    {
32	        parent::setUp();
33	
