5	namespace AtrioTeam\DigitalHub\Filament\Forms\Components;
6	
7	use Filament\Forms\Components\Field;
8	use Illuminate\Database\Eloquent\Model;
9	use Illuminate\Database\Eloquent\Relations\BelongsToMany;
10	
11	/**
12	 * Selettore a checkbox annidati: le categorie sono righe collassabili
13	 * (accordion) con un checkbox padre a tre stati; espandendo la categoria si
14	 * apre l'elenco dei suoi item come dropdown di checkbox.
15	 *
16	 * Selezionando la categoria si attivano tutti gli item; deselezionando un item
17	 * la categoria non risulta più tutta selezionata (stato indeterminate). La
18	 * relazione è salvata sempre a livello di singolo item, tramite `sync()` su una
19	 * BelongsToMany del record ospitante.
20	 *
21	 * Campo generico del core: non conosce i modelli di dominio del template, che
22	 * vengono passati come class-string a {@see self::relationship()}.
23	 */
24	class NestedCheckboxSelect extends Field
25	{
26	    protected string $view = 'digital-hub::filament.forms.components.nested-checkbox-select';
27	
28	    /** @var class-string<Model> */
29	    protected string $itemModel;
30	
31	    /** @var class-string<Model> */
32	    protected string $categoryModel;
33	
34	    protected string $categoryForeignKey;
35	
36	    protected string $noCategoryLabel = '';
37	
38	    /**
39	     * Configura la sorgente e il salvataggio della relazione BelongsToMany.
40	     *
41	     * @param string $name nome della relazione BelongsToMany sul record ospitante
42	     * @param class-string<Model> $itemModel modello degli item (es. Material/Fabric)
43	     * @param class-string<Model> $categoryModel modello della categoria
44	     * @param string $categoryForeignKey FK sull'item verso la categoria
45	     * @param string $noCategoryLabel etichetta per gli item senza categoria
46	     */
47	    public function relationship(
48	        string $name,
49	        string $itemModel,
50	        string $categoryModel,
51	        string $categoryForeignKey,
52	        string $noCategoryLabel,
53	    ): static {
54	        $this->itemModel = $itemModel;
55	        $this->categoryModel = $categoryModel;
56	        $this->categoryForeignKey = $categoryForeignKey;
57	        $this->noCategoryLabel = $noCategoryLabel;
58	
59	        // lo stato è un array sintetico di id: non è una colonna del modello
60	        $this->dehydrated(false);
61	
62	        $this->loadStateFromRelationshipsUsing(static function (NestedCheckboxSelect $component, Model $record) use ($name): void {
63	            $relation = self::relationOf($record, $name);
64	            $component->state(
65	                $relation->pluck($relation->getRelated()->getKeyName())
66	                    ->map(fn (mixed $id): string => is_numeric($id) ? (string) (int) $id : '')
67	                    ->all(),
68	            );
69	        });
70	
71	        $this->saveRelationshipsUsing(static function (NestedCheckboxSelect $component, Model $record) use ($name): void {
72	            $selected = collect((array) $component->getState())
73	                ->map(fn (mixed $id): int => is_numeric($id) ? (int) $id : 0)
74	                ->filter()
75	                ->values()
76	                ->all();
77	
78	            self::relationOf($record, $name)->sync($selected);
79	        });
80	
81	        return $this;
82	    }
83	
84	    /**
85	     * Categorie con i loro item, pronte per la view.
86	     *
87	     * @return list<array{key:string,label:string,ids:list<string>,options:list<array{id:string,label:string}>}>
88	     */
89	    public function getGroups(): array
90	    {
91	        $keyOf = static fn (Model $model): int => is_numeric($key = $model->getKey()) ? (int) $key : 0;
92	        $nameOf = static fn (Model $model): string => is_scalar($name = $model->getAttribute('name')) ? (string) $name : '';
93	
94	        $categoryModel = $this->categoryModel;
95	        $itemModel = $this->itemModel;
96	
97	        /** @var array<int, string> $categoryNames */
98	        $categoryNames = $categoryModel::query()
99	            ->get()
100	            ->mapWithKeys(fn (Model $category): array => [$keyOf($category) => $nameOf($category)])
101	            ->all();
102	
103	        // item raggruppati per categoria; ogni gruppo ordinato per nome (tradotto)
104	        $groups = $itemModel::query()
105	            ->get()
106	            ->sortBy($nameOf)
107	            ->groupBy(fn (Model $item): int|string => is_numeric($fk = $item->getAttribute($this->categoryForeignKey)) ? (int) $fk : '');
108	
109	        $result = [];
110	
111	        foreach ($groups as $categoryId => $items) {
112	            /** @var list<array{id:string,label:string}> $options */
113	            $options = $items->map(fn (Model $item): array => [
114	                'id' => (string) $keyOf($item),
115	                'label' => $nameOf($item),
116	            ])->values()->all();
117	
118	            $result[] = [
119	                'key' => (string) $categoryId,
120	                'label' => $categoryNames[$categoryId] ?? $this->noCategoryLabel,
121	                'ids' => array_column($options, 'id'),
122	                'options' => $options,
123	            ];
124	        }
125	
126	        return $result;
127	    }
128	
129	    /**
130	     * @return BelongsToMany<Model, Model>
131	     */
132	    private static function relationOf(Model $record, string $name): BelongsToMany
133	    {
134	        /** @var BelongsToMany<Model, Model> $relation */
135	        $relation = $record->{$name}();
136	
137	        return $relation;
138	    }
139	}
