166	    private static function groups(string $entityAlias, TagTarget $target, ?Closure $scopeGroups): array
167	    {
168	        $groupQuery = TagGroup::query()
169	            ->where('entity_type', $entityAlias)
170	            ->where('target', $target->value)
171	            ->whereHas('categories', function (Builder $categoryQuery): void {
172	                $categoryQuery->whereHas('tags');
173	            })
174	            ->with('categories.tags')
175	            ->orderBy('id');
176	
177	        if ($scopeGroups !== null) {
