101	     * di queste categorie: più Fieldset di gruppo possono così condividere la
102	     * stessa relazione senza toccare le selezioni degli altri gruppi.
103	     */
104	    private static function relationshipGroupFieldset(TagGroup $group): Fieldset
105	    {
106	        $categories = $group->categories
107	            ->filter(fn (TagCategory $category): bool => $category->tags->isNotEmpty())
108	            ->sortBy('id')
109	            ->values();
110	
111	        return Fieldset::make((string) $group->name)
112	            ->columnSpanFull()
113	            ->schema([
114	                NestedCheckboxSelect::make('tags_group_' . $group->id)
115	                    ->hiddenLabel()
116	                    ->relationship('tags', Tag::class, TagCategory::class, 'tag_category_id', '')
117	                    ->categories($categories)
118	                    ->items($categories->flatMap(fn (TagCategory $category) => $category->tags)),
119	            ]);
