124	     * annidato `tags.{categoryId}` tiene tutte le selezioni sotto `tags`.
125	     */
126	    private static function categorySelect(TagCategory $category): Select
127	    {
128	        $options = [];
129	        foreach ($category->tags as $tag) {
130	            $options[(int) $tag->id] = (string) $tag->name;
131	        }
132	
133	        return Select::make('tags.' . (int) $category->id)
134	            ->label((string) $category->name)
135	            ->multiple()
136	            ->searchable()
137	            ->options($options)
138	            ->default([]);
