2	
3	declare(strict_types=1);
4	
5	namespace AtrioTeam\DigitalHub\Filament\Forms\Components;
6	
7	use Filament\Forms\Components\Field;
8	use Illuminate\Database\Eloquent\Collection;
9	use Illuminate\Database\Eloquent\Model;
10	use Illuminate\Database\Eloquent\Relations\BelongsToMany;
11	
12	/**
13	 * Selettore a checkbox annidati: le categorie sono righe collassabili
14	 * (accordion) con un checkbox padre a tre stati; espandendo la categoria si
15	 * apre l'elenco dei suoi item come dropdown di checkbox.
16	 *
17	 * Selezionando la categoria si attivano tutti gli item; deselezionando un item
18	 * la categoria non risulta più tutta selezionata (stato indeterminate). La
19	 * relazione è salvata sempre a livello di singolo item, sincronizzando solo
20	 * gli id nell'"universo" del campo (quelli offerti come opzioni): questo
21	 * permette a più istanze di condividere la stessa relazione (es. `tags`
22	 * scopato per gruppo) senza cancellarsi a vicenda le selezioni.
23	 *
24	 * Campo generico del core: non conosce i modelli di dominio del template, che
25	 * vengono passati come class-string a {@see self::relationship()}. Categorie
26	 * e item possono anche essere iniettati già filtrati/eager-loaded tramite
27	 * {@see self::categories()} e {@see self::items()}, per i casi in cui il
28	 * chiamante deve scoparli (es. per gruppo) invece di caricare l'intera tabella.
29	 */
30	class NestedCheckboxSelect extends Field
31	{
32	    protected string $view = 'digital-hub::filament.forms.components.nested-checkbox-select';
33	
34	    /** @var class-string<Model> */
35	    protected string $itemModel;
36	
37	    /** @var class-string<Model> */
38	    protected string $categoryModel;
39	
40	    protected string $categoryForeignKey;
41	
42	    protected string $noCategoryLabel = '';
43	
44	    /** @var Collection<int, Model>|null override esplicito, bypassa la query su $categoryModel */
45	    protected ?Collection $categories = null;
46	
47	    /** @var Collection<int, Model>|null override esplicito, bypassa la query su $itemModel */
48	    protected ?Collection $items = null;
49	
50	    /**
51	     * Configura la sorgente e il salvataggio della relazione BelongsToMany.
52	     *
53	     * @param string $name nome della relazione BelongsToMany sul record ospitante
54	     * @param class-string<Model> $itemModel modello degli item (es. Material/Fabric), usato se {@see self::items()} non è impostato
55	     * @param class-string<Model> $categoryModel modello della categoria, usato se {@see self::categories()} non è impostato
56	     * @param string $categoryForeignKey FK sull'item verso la categoria
57	     * @param string $noCategoryLabel etichetta per gli item senza categoria
58	     */
59	    public function relationship(
60	        string $name,
61	        string $itemModel,
62	        string $categoryModel,
63	        string $categoryForeignKey,
64	        string $noCategoryLabel,
65	    ): static {
66	        $this->itemModel = $itemModel;
67	        $this->categoryModel = $categoryModel;
68	        $this->categoryForeignKey = $categoryForeignKey;
69	        $this->noCategoryLabel = $noCategoryLabel;
70	
71	        // lo stato è un array sintetico di id: non è una colonna del modello
72	        $this->dehydrated(false);
73	
74	        $this->loadStateFromRelationshipsUsing(static function (NestedCheckboxSelect $component, ?Model $record) use ($name): void {
75	            if ($record === null) {
76	                return;
77	            }
78	
79	            $relation = self::relationOf($record, $name);
80	            $relatedIds = $relation->pluck($relation->getRelated()->getKeyName())
81	                ->map(fn (mixed $id): string => is_numeric($id) ? (string) (int) $id : '')
82	                ->all();
83	
84	            // limitato all'universo del campo: la relazione può essere
85	            // condivisa con altre istanze scopate su altri gruppi/categorie
86	            $component->state(array_values(array_intersect($relatedIds, $component->universeIds())));
87	        });
88	
89	        $this->saveRelationshipsUsing(static function (NestedCheckboxSelect $component, ?Model $record) use ($name): void {
90	            if ($record === null) {
91	                return;
92	            }
93	
94	            $universe = $component->universeIds();
95	            $selected = collect((array) $component->getState())
96	                ->map(fn (mixed $id): string => is_numeric($id) ? (string) (int) $id : '')
97	                ->filter()
98	                ->intersect($universe)
99	                ->values()
100	                ->all();
101	
102	            // sync ristretto all'universo: non tocca gli id di relazioni
103	            // condivise che appartengono ad altre istanze del campo
104	            $relation = self::relationOf($record, $name);
105	            $relation->detach(array_values(array_diff($universe, $selected)));
106	            $relation->syncWithoutDetaching($selected);
107	        });
108	
109	        return $this;
110	    }
111	
112	    /**
113	     * Categorie iniettate dal chiamante (già filtrate/eager-loaded), al posto
114	     * della query non scopata su $categoryModel.
115	     *
116	     * @param Collection<int, Model> $categories
117	     */
118	    public function categories(Collection $categories): static
119	    {
120	        $this->categories = $categories;
121	
122	        return $this;
123	    }
124	
125	    /**
126	     * Item iniettati dal chiamante (già filtrati/eager-loaded), al posto
127	     * della query non scopata su $itemModel.
128	     *
129	     * @param Collection<int, Model> $items
130	     */
131	    public function items(Collection $items): static
132	    {
133	        $this->items = $items;
134	
135	        return $this;
136	    }
137	
138	    /**
139	     * Categorie con i loro item, pronte per la view.
140	     *
141	     * @return list<array{key:string,label:string,ids:list<string>,options:list<array{id:string,label:string}>}>
142	     */
143	    public function getGroups(): array
144	    {
145	        $keyOf = static fn (Model $model): int => is_numeric($key = $model->getKey()) ? (int) $key : 0;
146	        $nameOf = static fn (Model $model): string => is_scalar($name = $model->getAttribute('name')) ? (string) $name : '';
147	
148	        $categoryModel = $this->categoryModel;
149	        $itemModel = $this->itemModel;
150	
151	        /** @var array<int, string> $categoryNames */
152	        $categoryNames = ($this->categories ?? $categoryModel::query()->get())
153	            ->mapWithKeys(fn (Model $category): array => [$keyOf($category) => $nameOf($category)])
154	            ->all();
155	
156	        // item raggruppati per categoria; ogni gruppo ordinato per nome (tradotto)
157	        $groups = ($this->items ?? $itemModel::query()->get())
158	            ->sortBy($nameOf)
159	            ->groupBy(fn (Model $item): int|string => is_numeric($fk = $item->getAttribute($this->categoryForeignKey)) ? (int) $fk : '');
160	
161	        $result = [];
162	
163	        foreach ($groups as $categoryId => $items) {
164	            /** @var list<array{id:string,label:string}> $options */
165	            $options = $items->map(fn (Model $item): array => [
166	                'id' => (string) $keyOf($item),
167	                'label' => $nameOf($item),
168	            ])->values()->all();
169	
170	            $result[] = [
171	                'key' => (string) $categoryId,
172	                'label' => $categoryNames[$categoryId] ?? $this->noCategoryLabel,
173	                'ids' => array_column($options, 'id'),
174	                'options' => $options,
175	            ];
176	        }
177	
178	        return $result;
179	    }
180	
181	    /**
182	     * Tutti gli id di item offerti come opzioni dal campo, a prescindere dalla
183	     * categoria: è l'universo su cui load/save operano quando la relazione è
184	     * condivisa con altre istanze scopate diversamente.
185	     *
186	     * @return list<string>
187	     */
188	    private function universeIds(): array
189	    {
190	        return collect($this->getGroups())->flatMap(fn (array $group): array => $group['ids'])->values()->all();
191	    }
192	
193	    /**
194	     * @return BelongsToMany<Model, Model>
195	     */
196	    private static function relationOf(Model $record, string $name): BelongsToMany
197	    {
198	        /** @var BelongsToMany<Model, Model> $relation */
199	        $relation = $record->{$name}();
200	
201	        return $relation;
202	    }
203	}
